#!/usr/bin/env python3
"""Render the public version history from reviewed release content."""
import html
import json
from site_shell import shared_shell
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
config = json.loads((ROOT / 'content/releases.json').read_text())
e = html.escape
sections = []
for index, release in enumerate(config['releases']):
    version = release['version']
    rows = ''.join('<tr><th scope="row">'+e(c['feature'])+'</th><td>'+e(c['change'])+'</td><td>'+e(c['benefit'])+'</td></tr>' for c in release['changes'])
    samples = '<p>Try the synthetic inputs: <a href="assets/samples/merge-api.log" download="api.log">api.log</a> · <a href="assets/samples/merge-worker.log" download="worker.log">worker.log</a> · <a href="assets/samples/merge-auth.log" download="auth.log">auth.log</a>. Save them with these filenames.</p>' if index == 0 else ''
    visuals = ''
    if index == 0:
        visuals = '<figure class="product-shot"><a href="/assets/screens/live-merge.png" target="_blank" rel="noopener"><img src="/assets/screens/live-merge.webp" alt="Flik 0.3.0 live merge with colored service filenames, API timeout and worker retry" width="1488" height="772" loading="lazy"></a><figcaption>Live multi-file merge in Flik 0.3.0. Real terminal capture with synthetic incident logs. <a href="/use-cases.html#live-merge">Reproduce this investigation →</a></figcaption></figure><figure class="product-shot"><a href="/assets/screens/long-split.png" target="_blank" rel="noopener"><img src="/assets/screens/long-split.webp" alt="Three consecutive pages of log history in Flik long-split mode" width="2208" height="724" loading="lazy"></a><figcaption>The three-column layout in 0.3.0. <a href="/use-cases.html#long-split">Try the same input →</a></figcaption></figure>'
    sections.append(f''' <section id="v{version}"><p class="eyebrow">{'LATEST · ' if index == 0 else ''}FLIK {version} · {e(release['date'])}</p><h2>{e(release['headline'])}</h2><p>{e(release['summary'])}</p>{visuals}<div class="table-wrap"><table><caption>Flik {version}: changes and practical benefits</caption><thead><tr><th>Feature</th><th>What changed</th><th>What it helps you do</th></tr></thead><tbody>{rows}</tbody></table></div><h3>Try it</h3><pre><code>{e(release['commands'])}</code></pre>{samples}<aside class="note"><strong>Scope and limits</strong><p>{e(release['limits'])}</p></aside><p><a href="https://github.com/torxx666/flik/releases/tag/v{version}">Flik {version} downloads and checksums →</a></p></section>''')
body = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>What’s new in Flik — version history</title><meta name="description" content="Flik release history: what changed, what each version helps you do, runnable commands and explicit limits."><link rel="canonical" href="https://flik.spedo.dev/changelog.html"><meta property="og:title" content="What’s new in Flik"><meta property="og:description" content="Changes, practical benefits and limits for each Flik release."><meta property="og:type" content="website"><meta property="og:url" content="https://flik.spedo.dev/changelog.html"><link rel="icon" href="assets/flik-mark.svg"><link rel="stylesheet" href="assets/guides.css"></head><body><a class="skip" href="#main">Skip to content</a><header><nav aria-label="Main navigation"><strong><a href="/">Flik</a></strong><a href="guides/">Practical guides</a><a href="changelog.html" aria-current="page">What’s new</a><a href="/#install">Download Flik →</a></nav></header><main id="main"><p class="eyebrow">FLIK / VERSION HISTORY</p><h1>What’s new in Flik</h1><p class="lead">What changed, what it brings to your investigation, and where the limits are.</p><nav aria-label="Release versions">{ ' · '.join('<a href="#v'+r['version']+'">'+r['version']+'</a>' for r in config['releases']) }</nav>{''.join(sections)}<section class="cta"><h2>Update to the latest version</h2><pre><code>brew update\nbrew upgrade torxx666/tap/flik\nflik --version</code></pre><p>For a first Homebrew installation, use <code>brew install torxx666/tap/flik</code>. You can also download the matching archive and SHA256SUMS directly.</p><a class="button" href="/#install">Download Flik →</a></section><p class="updated">Updated {e(config['updated_on'])}. Release dates match the public GitHub releases. Existing demonstrations may show an earlier interface; the changes above identify when features were introduced.</p></main><footer><div><a href="/">Flik product overview</a> · <a href="guides/">Practical guides</a> · <a href="https://github.com/torxx666/flik/blob/main/CHANGELOG.md">Source changelog</a></div></footer></body></html>'''
(ROOT / 'dist/changelog.html').write_text(shared_shell(body))
print('Built changelog.html for', len(sections), 'published versions')
